public class GTreeTableModel<T> : ThreadedTableModelStub<T> where T : GTreeTableNode {
	protected class TreeColumn : AbstractDynamicTableColumnStub<T, GTreeTableNode> {
		private string columnName;
		private GTreeTableCellRenderer<GTreeTableNode> renderer;

		public TreeColumn(string columnName) {
